(6572146, 979020, 124815, '<td valign="top">The title helps the shot. We feel the  heat and the awful buzzing. We feel for the girl.</td>', 'The title helps the shot. We feel the  heat and the awful buzzing. We feel for the girl.', '2011-10-20 00:43:17.000000', NULL, 1),
(6572147, 979444, 124815, '<td valign="top">Some kind of Librodo approach to match the sadness of this boy.</td>', 'Some kind of Librodo approach to match the sadness of this boy.', '2011-10-20 00:43:28.000000', NULL, 1),
(6572148, 979289, 124815, '<td valign="top">Cute idea. The photo is not up to the original idea though.</td>', 'Cute idea. The photo is not up to the original idea though.', '2011-10-20 00:43:40.000000', NULL, 1),
(6572149, 978743, 124815, '<td valign="top">With a baby like this you could have taken a more spectacular picture than a snapshot.</td>', 'With a baby like this you could have taken a more spectacular picture than a snapshot.', '2011-10-20 00:43:49.000000', NULL, 1),
(6572150, 979373, 124815, '<td valign="top">a baby is a baby is a baby<br/>when they grow, it will be a different matter!</td>', 'a baby is a baby is a babywhen they grow, it will be a different matter!', '2011-10-20 00:44:46.000000', NULL, 1),
(6572151, 979424, 124815, '<td valign="top">The talking kitten! You have to sell the picture to the toy makers and I''ll buy a few of them.</td>', 'The talking kitten! You have to sell the picture to the toy makers and I''ll buy a few of them.', '2011-10-20 00:44:57.000000', NULL, 1),
(6572186, 979251, 23439, '<td valign="top">This has potential to be a good image, but the black dots in the shadow areas really ruin it for me. Was the lighting really dim for this? To me it looks like maybe the shadows were brightened up too much in post leaving them really grainy, but I''ve never seen noise that looked quite like that. Maybe the conversion to B&amp;W amplified it as well. If you didn''t see what I''m talking about when editing your image, make sure your monitor is calibrated so you can see all the shades of white and black when you preview your image</td>', 'This has potential to be a good image, but the black dots in the shadow areas really ruin it for me. Was the lighting really dim for this? To me it looks like maybe the shadows were brightened up too much in post leaving them really grainy, but I''ve never seen noise that looked quite like that. Maybe the conversion to B&W amplified it as well. If you didn''t see what I''m talking about when editing your image, make sure your monitor is calibrated so you can see all the shades of white and black when you preview your image', '2011-10-20 02:32:20.000000', NULL, 1),
(6572189, 979200, 36843, '<td valign="top">Wow, I just love this shot, and dad in the background just makes it all the stronger</td>', 'Wow, I just love this shot, and dad in the background just makes it all the stronger', '2011-10-20 02:43:34.000000', NULL, 1),
(6572234, 978623, 674, '<td valign="top">would like to see more eye contact with the photographer.</td>', 'would like to see more eye contact with the photographer.', '2011-10-20 05:45:11.000000', NULL, 1),
(6572235, 979250, 674, '<td valign="top">I find this too staged and cluttered and both dogs look too old to be toddlers let alone babies</td>', 'I find this too staged and cluttered and both dogs look too old to be toddlers let alone babies', '2011-10-20 05:46:51.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(6572260, 979430, 101702, '<td valign="top">Great title :-) I''m not sure I like the ringlight catchlights... seem a bit overpowering and make the baby look a bit alien. Facial expression is perfect though, and I expect this to be on the front page.</td>', 'Great title :-) I''m not sure I like the ringlight catchlights... seem a bit overpowering and make the baby look a bit alien. Facial expression is perfect though, and I expect this to be on the front page.', '2011-10-20 07:40:31.000000', NULL, 1),
(6572264, 979403, 101702, '<td valign="top">This is the 72nd image I have seen in this challenge, and is the one I am struggling the most with. The majority of images in this challenge are poor quality and there are quite a few that do not meet the challenge. That was my first instinct on seeing this (I tend to view images without looking at the title to avoid shoehorn images). I saw no baby so was about to mark it as a DNMC, but then I saw the title and really looked at this image. Whilst not the most technically adept image on show in the challenge, it is without doubt the most touching and thought provoking.</td>', 'This is the 72nd image I have seen in this challenge, and is the one I am struggling the most with. The majority of images in this challenge are poor quality and there are quite a few that do not meet the challenge. That was my first instinct on seeing this (I tend to view images without looking at the title to avoid shoehorn images). I saw no baby so was about to mark it as a DNMC, but then I saw the title and really looked at this image. Whilst not the most technically adept image on show in the challenge, it is without doubt the most touching and thought provoking.', '2011-10-20 07:53:56.000000', NULL, 1),
